const deities = ['Shiva','Ganesha','Vishnu','Durga','Hanuman','Krishna']
const offerings = ['Flowers','Diya','Prasad']
const sections = ['darshan','audio','reading','panchang','horoscope','event']
const topics = {
  temples: [
    {id:'mahakal',name:'Shri Mahakaleshwar',city:'Ujjain',description:'Jyotirlinga and the center of Mahakal worship in Avantika.',deity:'Shiva'},
    {id:'mangalnath',name:'Mangalnath Temple',city:'Ujjain',description:'Traditional site for Mangal Bhaat Puja.',deity:'Shiva'},
    {id:'harsiddhi',name:'Harsiddhi Temple',city:'Ujjain',description:'A Devi temple near the Mahakal precinct.',deity:'Durga'},
    {id:'gopal',name:'Gopal Mandir',city:'Ujjain',description:'A temple dedicated to Krishna in the old city.',deity:'Krishna'},
    {id:'omkareshwar',name:'Shri Omkareshwar',city:'Mandhata',description:'A Jyotirlinga on the Narmada.',deity:'Shiva'}
  ],
  chadhava: [
    {id:'flower',name:'Flower offering',description:'Request a flower offering in your name.'},
    {id:'lamp',name:'Deep offering',description:'Request a diya offering with your Sankalp.'},
    {id:'bhog',name:'Bhog offering',description:'Request a traditional bhog offering.'}
  ],
  store: [
    {id:'mala',name:'Jaap mala',description:'Request availability and a quote for a 108-bead mala.'},
    {id:'diya',name:'Puja diya',description:'Request availability and a quote for a diya.'},
    {id:'kit',name:'Home puja samagri',description:'Request a quote for supplies suited to your ceremony.'}
  ]
}
const initial = [
  {id:'sankalp',category:'reading',title:'Preparing a Sankalp',text:'Before beginning, prepare the name, family or Gotra where customary, and the intention you wish to state. Ask the officiating priest which details are needed.'},
  {id:'aarti',category:'reading',title:'Aarti at home',text:'Set the diya on a stable surface. Follow your familyâ€™s order of worship, offer flowers if customary, and conclude with a moment of quiet prayer.'},
  {id:'japa',category:'reading',title:'Counting a mala',text:'Set an intention for your practice and count one bead after each repetition. Avantikaâ€™s Jaap Mala saves your count on this device.'}
]
function devotionalApi(db,{send,read,field,date,href,fail,today,randomUUID}) {

  const addContent = db.prepare('INSERT OR IGNORE INTO devotional_content VALUES (?,?,?,?,?,?,?,?)')
  return async function devotional(req,res,path,user) {
    const method=req.method
    if (path==='/api/devotional' && method==='GET') {
      const content = await db.prepare('SELECT * FROM devotional_content ORDER BY day DESC,created DESC LIMIT 150').all()
      const defaults=initial.filter(item=>!content.some(saved=>saved.id===item.id))
      send(res,{...topics,deities,offerings,sections,content:[...content,...defaults],today:today()})
      return true
    }
    if (!['/api/mandir','/api/community','/api/devotional/content'].includes(path) && !path.startsWith('/api/community/')) return false
    if (path==='/api/mandir') {
      if (!user) fail(401,'Sign in to save your mandir.')
      if (method==='PUT') {
        const input=await read(req)
        if (!deities.includes(input.deity)) fail(400,'Choose a deity.')
        await db.prepare('INSERT INTO mandirs VALUES (?,?) ON CONFLICT(owner) DO UPDATE SET deity=excluded.deity').run(user.id,input.deity)
      } else if (method==='POST') {
        const input=await read(req)
        if (!offerings.includes(input.offering)) fail(400,'Choose an offering.')
        if (!(await db.prepare('SELECT 1 FROM mandirs WHERE owner=?').get(user.id))) fail(409,'Save your mandir first.')
        await db.prepare('INSERT INTO mandir_activity VALUES (?,?,?,1) ON CONFLICT(owner,day,offering) DO UPDATE SET total=total+1').run(user.id,today(),input.offering)
      } else if (method!=='GET') return false
      const selected=await db.prepare('SELECT deity FROM mandirs WHERE owner=?').get(user.id)
      const activity=await db.prepare('SELECT day,offering,total FROM mandir_activity WHERE owner=? ORDER BY day DESC LIMIT 90').all(user.id)
      send(res,{deity:selected?.deity||null,activity})
      return true
    }
    if (path==='/api/devotional/content' && method==='POST') {
      if (user?.role!=='admin') fail(403,'Operations access is required.')
      const input=await read(req)
      const category=field(input,'category',20,true)
      if (!sections.includes(category)) fail(400,'Choose a content category.')
      const temple=field(input,'temple',30)
      if (temple && !topics.temples.some(item=>item.id===temple)) fail(400,'Choose a temple.')
      const day=input.day?date(input,'day'):''
      if (['panchang','horoscope','event'].includes(category) && !day) fail(400,'Choose a date for this entry.')
      const entry={id:randomUUID(),category,title:field(input,'title',120,true),text:field(input,'text',3000,true),
        url:href(input,'url',['audio','darshan'].includes(category)),day,temple,created:new Date().toISOString()}
      await addContent.run(...Object.values(entry))
      send(res,entry,201)
      return true
    }
    if (path==='/api/community' && method==='GET') {
      const query='SELECT community_posts.id,title,text,state,created,users.name AS author FROM community_posts JOIN users ON users.id=owner '
      const order=' ORDER BY created DESC LIMIT 75'
      const posts=user?.role==='admin'?await db.prepare(query+order).all():
        user?await db.prepare(query+"WHERE state='Published' OR owner=?"+order).all(user.id):
          await db.prepare(query+"WHERE state='Published'"+order).all()
      send(res,{posts})
      return true
    }
    if (path==='/api/community' && method==='POST') {
      if (!user) fail(401,'Sign in to submit a post.')
      const input=await read(req)
      const id=randomUUID()
      await db.prepare('INSERT INTO community_posts VALUES (?,?,?,?,?,?)').run(id,user.id,field(input,'title',100,true),
        field(input,'text',1500,true),'Pending',new Date().toISOString())
      send(res,{id,state:'Pending'},201)
      return true
    }
    if (path.startsWith('/api/community/') && method==='PATCH') {
      if (user?.role!=='admin') fail(403,'Operations access is required.')
      const id=path.split('/').at(-1)
      const {state}=await read(req)
      if (!['Published','Hidden'].includes(state)) fail(400,'Choose a moderation action.')
      const change=await db.prepare('UPDATE community_posts SET state=? WHERE id=?').run(state,id)
      if (!change.changes) fail(404,'Post not found.')
      send(res,{id,state})
      return true
    }
    return false
  }
}

function retailApi(db,{send,read,field,href,fail}) {
  const cart = owner => db.prepare('SELECT p.id,p.name,p.price,p.stock,p.active,c.quantity FROM cart c JOIN products p ON p.id=c.product WHERE c.owner=? ORDER BY p.name').all(owner)
  const stages={Submitted:'Confirmed',Confirmed:'Dispatched',Dispatched:'Delivered'}
  return async (req,res,path,user) => {
    if (!path.startsWith('/api/shop/')) return false
    const method=req.method
    const route=path.slice('/api/shop/'.length)
    if (route==='products' && method==='GET') {
      const products=await db.prepare(user?.role==='admin'?'SELECT * FROM products ORDER BY name':'SELECT * FROM products WHERE active=1 ORDER BY name').all()
      send(res,{products})
      return true
    }
    if (!user) fail(401,'Sign in to continue.')
    if (route==='products' && method==='PUT') {
      if (user.role!=='admin') fail(403,'Operations access is required.')
      const input=await read(req)
      const id=field(input,'id',40,true)
      if (!/^[a-z0-9-]+$/.test(id) || !Number.isSafeInteger(input.price) || input.price<1 || input.price>100000 || !Number.isSafeInteger(input.stock) || input.stock<0 || input.stock>100000 || typeof input.active!=='boolean') fail(400,'Check the product ID, price and inventory.')
      await db.prepare('INSERT INTO products VALUES (?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,price=excluded.price,stock=excluded.stock,active=excluded.active')
        .run(id,field(input,'name',100,true),field(input,'description',900,true),input.price,input.stock,input.active?1:0)
      send(res,{id});return true
    }
    if (route==='cart' && ['GET','PUT'].includes(method)) {
      if (user.role!=='devotee') fail(403,'Use a devotee account to shop.')
      if (method==='PUT') {
        const input=await read(req)
        const id=field(input,'product',40,true)
        const quantity=input.quantity
        if (!Number.isInteger(quantity)||quantity<0||quantity>20) fail(400,'Enter a quantity from 0 to 20.')
        if (quantity===0) await db.prepare('DELETE FROM cart WHERE owner=? AND product=?').run(user.id,id)
        else {
          const change=await db.prepare('INSERT INTO cart SELECT ?,id,? FROM products WHERE id=? AND active=1 AND stock>=? ON CONFLICT(owner,product) DO UPDATE SET quantity=excluded.quantity').run(user.id,quantity,id,quantity)
          if (!change.changes) fail(409,'This quantity is unavailable.')
        }
      }
      send(res,{items:await cart(user.id)});return true
    }
    if (route==='orders' && method==='POST') {
      if (user.role!=='devotee') fail(403,'Use a devotee account to place an order.')
      const input=await read(req)
      const id=field(input,'id',36,true)
      const pin=field(input,'pin',6,true)
      if (!/^[a-f0-9-]{36}$/.test(id)||! /^[1-9]\d{5}$/.test(pin)||!Number.isSafeInteger(input.total)||input.total<1) fail(400,'Check the PIN and order total.')
      const change=await db.prepare(`
        INSERT INTO retail_orders(id,owner,name,address,pin,status,total,created)
        SELECT ?,?,?,?,?, 'Submitted',SUM(p.price*c.quantity),?
        FROM cart c JOIN products p ON p.id=c.product WHERE c.owner=?
        HAVING COUNT(*)>0 AND SUM(p.price*c.quantity)=? AND MIN(p.active)=1 AND MIN(p.stock-c.quantity)>=0
        ON CONFLICT(id) DO NOTHING
      `).run(id,user.id,field(input,'name',100,true),field(input,'address',450,true),pin,new Date().toISOString(),user.id,input.total)
      if (!change.changes) {
        const saved=await db.prepare('SELECT id FROM retail_orders WHERE id=? AND owner=?').get(id,user.id)
        if (!saved) fail(409,'Cart prices or stock changed. Review your cart and try again.')
      }
      send(res,{id},change.changes?201:200);return true
    }
    if (route==='orders' && method==='GET') {
      if (!['devotee','admin'].includes(user.role)) fail(403,'Orders are available to devotees and operations.')
      const where=user.role==='admin'?'':' WHERE o.owner=?'
      const rows=await db.prepare(`SELECT o.*,l.product,l.name AS item,l.price,l.quantity FROM retail_orders o JOIN retail_lines l ON l.order_id=o.id
        JOIN (SELECT id FROM retail_orders${user.role==='admin'?'':' WHERE owner=?'} ORDER BY created DESC LIMIT 50) recent ON recent.id=o.id${where}
        ORDER BY o.created DESC,l.name`).all(...(where?[user.id,user.id]:[]))
      const orders=new Map()
      for (const row of rows) {
        const {product,item,price,quantity,...order}=row
        if (!orders.has(row.id)) orders.set(row.id,{...order,items:[]})
        orders.get(row.id).items.push({product,name:item,price,quantity})
      }
      send(res,{orders:[...orders.values()]});return true
    }
    if (route.startsWith('orders/') && method==='PATCH') {
      const id=route.split('/')[1]
      const input=await read(req)
      const order=await db.prepare('SELECT owner,status FROM retail_orders WHERE id=?').get(id)
      if (!order||(user.role!=='admin'&&order.owner!==user.id)) fail(404,'Order not found.')
      if (order.status!==input.expected) fail(409,'The order changed. Refresh and try again.')
      const cancel=input.action==='cancel'
      const next=cancel&&['Submitted','Confirmed'].includes(order.status)?'Cancelled':!cancel&&user.role==='admin'?stages[order.status]:null
      if (!next) fail(403,'This order cannot be changed.')
      const tracking=next==='Dispatched'?href(input,'tracking'):''
      const changed=await db.prepare("UPDATE retail_orders SET status=?,tracking=CASE WHEN ?='' THEN tracking ELSE ? END WHERE id=? AND status=?")
        .run(next,tracking,tracking,id,order.status)
      if (!changed.changes) fail(409,'The order changed. Refresh and try again.')
      send(res,{id,status:next});return true
    }
    fail(404,'Shop route not found.')
  }
}

const solarCities = {
  Ujjain:[23.1765,75.7885],Indore:[22.7196,75.8577],Varanasi:[25.3176,82.9739],
  Delhi:[28.6139,77.2090],Mumbai:[19.0760,72.8777],Bengaluru:[12.9716,77.5946]
}
function solarTimes(city,day) {
  const [latitude,longitude]=solarCities[city]
  const instant=new Date(day+'T12:00:00Z')
  const year=instant.getUTCFullYear()
  const first=Date.UTC(year,0,1,12)
  const yearDays=(Date.UTC(year+1,0,1)-Date.UTC(year,0,1))/86400000
  const angle=2*Math.PI*(instant.getTime()-first)/86400000/yearDays
  const eq=229.18*(0.000075+0.001868*Math.cos(angle)-0.032077*Math.sin(angle)-
    0.014615*Math.cos(2*angle)-0.040849*Math.sin(2*angle))
  const declination=0.006918-0.399912*Math.cos(angle)+0.070257*Math.sin(angle)-
    0.006758*Math.cos(2*angle)+0.000907*Math.sin(2*angle)-0.002697*Math.cos(3*angle)+0.00148*Math.sin(3*angle)
  const radians=Math.PI/180
  const lat=latitude*radians
  const cosHour=(Math.cos(90.833*radians)-Math.sin(lat)*Math.sin(declination))/(Math.cos(lat)*Math.cos(declination))
  const minutes=4*Math.acos(cosHour)/radians
  const noon=720-4*longitude-eq+330
  const format=value=>{
    const round=Math.round(value)
    return String(Math.floor(round/60)).padStart(2,'0')+':'+String(round%60).padStart(2,'0')
  }
  return {city,day,timeZone:'Asia/Kolkata',sunrise:format(noon-minutes),solarNoon:format(noon),sunset:format(noon+minutes)}
}

const hex = bytes => Array.from(bytes,byte=>byte.toString(16).padStart(2,'0')).join('')
const random = bytes => hex(crypto.getRandomValues(new Uint8Array(bytes)))
const randomUUID = () => crypto.randomUUID()
const encoder = new TextEncoder()
async function passwordDigest(password,salt,iterations) {
  const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits'])
  return hex(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:encoder.encode(salt),iterations,hash:'SHA-256'},key,256)))
}
async function hash(password,rounds) {
  const salt=random(16)
  return 'pbkdf2:'+rounds+':'+salt+':'+await passwordDigest(password,salt,rounds)
}
async function verify(password,stored,verifyLegacy) {
  const parts=stored.split(':')
  const [format,rounds,salt,digest]=parts.length===3?[parts[0],600000,...parts.slice(1)]:parts
  if (format!=='pbkdf2') return verifyLegacy?.(password,stored)||false
  const iterations=Number(rounds)
  if (![100000,600000].includes(iterations)) return false
  const actual=await passwordDigest(password,salt,iterations)
  if (!digest || digest.length!==actual.length) return false
  let difference=0
  for (let i=0;i<actual.length;i++) difference|=actual.charCodeAt(i)^digest.charCodeAt(i)
  return difference===0
}
const tokenHash = async token => hex(new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(token))))
const timeZone = 'Asia/Kolkata'
const today = () => new Intl.DateTimeFormat('sv-SE', { timeZone }).format(new Date())
const statuses = {
  pooja: ['Requested', 'Assigned', 'Muhurat confirmed', 'Ritual in progress', 'Video ready', 'Prasad packed', 'Dispatched', 'Delivered'],
  daan: ['Requested', 'Assigned', 'Completed'],
  chadhava: ['Requested', 'Assigned', 'Completed'],
  store: ['Requested', 'Assigned', 'Completed'],
  consultation: ['Requested', 'Assigned', 'Scheduled', 'Completed'],
  astrology: ['Requested', 'Assigned', 'Completed'],
  support: ['Requested', 'Resolved']
}
function fail(status, message) { throw Object.assign(new Error(message), { status }) }
function send(res, value, status = 200) {
  res.writeHead(status, {'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'})
  res.end(JSON.stringify(value))
}
async function read(req) {
  if (!req.headers['content-type']?.startsWith('application/json')) fail(415, 'Use application/json.')
  const parts = []
  let length = 0
  for await (const chunk of req) {
    length += chunk.length
    if (length > 24000) fail(413, 'Request is too large.')
    parts.push(chunk)
  }
  try {
    const parsed = JSON.parse(await new Blob(parts).text())
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed
  } catch {}
  fail(400, 'Provide a valid request.')
}
function field(data, key, max, required = false) {
  const value = typeof data[key] === 'string' ? data[key].trim() : ''
  if (value.length > max || (required && !value)) fail(400, 'Check the ' + key + ' field.')
  return value
}
function date(data, key, future = false) {
  const value = field(data, key, 10, true)
  const parsed = new Date(value)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || !Number.isFinite(+parsed) ||
      parsed.toISOString().slice(0,10) !== value || (future && value < today())) fail(400, 'Enter a valid ' + key + '.')
  return value
}
function href(data, key, required = true) {
  const value = field(data, key, 1800, required)
  if (!value) return ''
  try {
    const url = new URL(value)
    if (url.protocol === 'https:' && !url.username && !url.password) return url.href
  } catch {}
  fail(400, 'Enter an HTTPS link.')
}
const view = ({id,name,email,role}) => ({id,name,email,role})
const requestView = row => ({...row, details:JSON.parse(row.details),history:JSON.parse(row.history)})
function booking(catalog, kind, input) {
  const name = field(input,'name',100,true)
  if (kind === 'pooja') {
    const ritual = catalog.rituals.find(item => item.id === input.service)
    if (!ritual) fail(400,'Choose a ritual.')
    if (!['proxy','visit'].includes(input.mode)) fail(400,'Choose a booking mode.')
    const deliver = input.mode === 'proxy' && input.deliver === true
    const pincode = deliver ? field(input,'pincode',6,true) : ''
    if (deliver && !/^[1-9]\d{5}$/.test(pincode)) fail(400,'Enter a six-digit Indian PIN code.')
    const delivery = deliver ? 99 : 0
    return [ritual.name, {name,mode:input.mode,date:date(input,'date',true),gotra:field(input,'gotra',80),
      family:field(input,'family',250),nakshatra:field(input,'nakshatra',80),rashi:field(input,'rashi',80),
      sankalp:field(input,'sankalp',1000,true),language:field(input,'language',30,true), deliver,pincode,
      address:deliver ? field(input,'address',450,true) : '',fee:ritual.fee,delivery,total:ritual.fee === null ? null : ritual.fee + delivery}]
  }
  if (kind === 'chadhava' || kind === 'store') {
    const item = topics[kind].find(entry => entry.id === input.service)
    if (!item) fail(400,'Choose a valid service.')
    const details = {name,note:field(input,'note',1000)}
    if (kind === 'chadhava') {
      const temple = topics.temples.find(entry=>entry.id===input.temple)
      if (!temple) fail(400,'Choose a temple.')
      details.temple = temple.name
      details.gotra = field(input,'gotra',80)
      details.sankalp = field(input,'sankalp',1000,true)
    } else {
      if (!Number.isInteger(input.amount) || input.amount < 1 || input.amount > 20) fail(400,'Choose a quantity from 1 to 20.')
      details.quantity = input.amount
    }
    return [item.name,details]
  }
  if (kind === 'daan') {
    if (!catalog.daan.some(item => item.name === input.service)) fail(400,'Choose a Daan option.')
    if (!Number.isInteger(input.amount) || input.amount < 1 || input.amount > 100000) fail(400,'Enter a whole amount between â‚¹1 and â‚¹100,000.')
    return [input.service,{name,amount:input.amount,note:field(input,'note',1000)}]
  }
  if (kind === 'support') return [field(input,'subject',100,true),{name,note:field(input,'note',1500,true)}]
  if (kind === 'consultation' || kind === 'astrology') {
    const topic = field(input,'service',100,true)
    if (!(kind === 'consultation' ? catalog.consult : catalog.astrology).includes(topic)) fail(400,'Choose a valid service.')
    const details = {name,note:field(input,'note',1000)}
    if (kind === 'consultation') {
      details.date = date(input,'date',true)
      details.channel = field(input,'channel',20,true)
      if (!['Chat','Audio','Video'].includes(details.channel)) fail(400,'Choose a consultation format.')
    } else {
      details.city = field(input,'city',100,true)
      if (['Janam Kundli','Kundli Milan'].includes(topic)) {
        details.birthDate = date(input,'birthDate')
        details.birthTime = field(input,'birthTime',5,true)
        if (details.birthDate > today() || !/^([01]\d|2[0-3]):[0-5]\d$/.test(details.birthTime)) fail(400,'Check the birth details.')
        if (topic === 'Kundli Milan') {
          details.secondName = field(input,'secondName',100,true)
          details.secondCity = field(input,'secondCity',100,true)
          details.secondDate = date(input,'secondDate')
          details.secondTime = field(input,'secondTime',5,true)
          if (details.secondDate > today() || !/^([01]\d|2[0-3]):[0-5]\d$/.test(details.secondTime)) fail(400,'Check the second birth profile.')
        }
      } else details.date = date(input,'date',topic === 'Shubh Muhurat')
    }
    return [topic,details]
  }
  fail(400,'Choose a service.')
}
async function transition(db, row, input, user) {
  const {kind, status, details} = row
  if (['Cancelled','Delivered','Completed','Resolved'].includes(status) ||
    (kind === 'pooja' && status === 'Video ready' && !details.deliver)) fail(409,'This request is closed.')
  if (input.action === 'cancel') {
    if (!((user.role === 'devotee' && status === 'Requested') || user.role === 'admin')) fail(403,'Cancellation is unavailable.')
    return 'Cancelled'
  }
  if (user.role === 'devotee') fail(403,'Only staff can advance requests.')
  if (kind === 'support' && user.role !== 'admin') fail(403,'Support is handled by operations.')
  if (kind === 'pooja' && ['Video ready','Prasad packed','Dispatched'].includes(status) && user.role !== 'admin') fail(403,'Dispatch is handled by operations.')
  const next = statuses[kind][statuses[kind].indexOf(status)+1]
  if (next === 'Assigned') row.assigned = user.role === 'pandit' ? user.id : field(input,'assignee',80,true)
  if (next === 'Assigned' && !(await db.prepare("SELECT id FROM users WHERE id=? AND role='pandit'").get(row.assigned))) fail(400,'Select a Pandit account.')
  if (next === 'Muhurat confirmed' || next === 'Scheduled') {
    details.confirmedDate = date(input,'confirmedDate',true)
    details.confirmedTime = field(input,'confirmedTime',5,true)
    if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(details.confirmedTime)) fail(400,'Enter a valid time in IST.')
  }
  if (next === 'Scheduled') details.meeting = href(input,'meeting',false)
  if (next === 'Video ready' && details.mode === 'proxy') details.video = href(input,'video')
  if (next === 'Video ready' && details.mode === 'visit') return 'Completed'
  if (next === 'Dispatched') {
    details.awb = field(input,'AWB',100,true)
    details.tracking = href(input,'tracking')
  }
  if (next === 'Completed' || next === 'Resolved') {
    details.result = field(input,'result',2000,true)
    details.proof = href(input,'proof',false)
  }
  return next
}

function createApplication({db,catalog,staffCode={},google,verifyLegacy,secure=false,passwordRounds=600000,authThrottle}) {
  const secureCookie=secure?'; Secure':''
  async function setSession(res, user) {
    const token = random(32)
    await db.prepare('DELETE FROM sessions WHERE expires <= ?').run(Date.now())
    await db.prepare('INSERT INTO sessions VALUES (?,?,?)').run(await tokenHash(token),user.id,Date.now()+86400000)
    res.appendHeader('Set-Cookie', 'avantika=' + token + '; HttpOnly; SameSite=Lax; Path=/; Max-Age=86400'+secureCookie)
  }
  async function establish(res,user) {
    await setSession(res,user)
    send(res,{user:view(user)})
  }
  const retail = retailApi(db,{send,read,field,href,fail})
  const devotional = devotionalApi(db,{send,read,field,date,href,fail,today,randomUUID})
  return async (req,res) => {
    res.setHeader('X-Content-Type-Options','nosniff')
    res.setHeader('Referrer-Policy','no-referrer')
    res.setHeader('Content-Security-Policy',"default-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
    try {
      const url = new URL(req.url,'https://'+req.headers.host)
      const path = url.pathname
      const method = req.method
      if (!path.startsWith('/api/')) fail(404,'Page not found.')
      if (['POST','PATCH','PUT'].includes(method) && req.headers.origin && req.headers.origin !== (secure?'https://':'http://') + req.headers.host) fail(403,'Invalid request origin.')
      const token = req.headers.cookie?.match(/(?:^|; )avantika=([a-f0-9]{64})(?:;|$)/)?.[1]
      const user = token && await db.prepare('SELECT users.* FROM users JOIN sessions ON users.id=sessions.owner WHERE token=? AND expires>?').get(await tokenHash(token),Date.now())
      if (method === 'GET' && path === '/api/session') return send(res,{user:user ? view(user) : null,googleSignIn:google?.available(req)||false})
      if (method === 'GET' && ['/api/login/google','/api/login/google/callback'].includes(path)) {
        if (!google?.available(req)) fail(503,'Google sign-in is unavailable at this address.')
        if (path.endsWith('/callback')) return await google.finish(req,res,url,setSession)
        return google.start(res,url)
      }
      if (method === 'POST' && path === '/api/logout') {
        if (token) await db.prepare('DELETE FROM sessions WHERE token=?').run(await tokenHash(token))
        res.setHeader('Set-Cookie','avantika=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0'+secureCookie)
        return send(res,{user:null})
      }
      if (method === 'POST' && ['/api/login','/api/register'].includes(path)) {
        const input = await read(req)
        const email = field(input,'email',180,true).toLowerCase()
        const password = field(input,'password',128,true)
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) fail(400,'Enter a valid email.')
        if (authThrottle) await authThrottle(req,path,email)
        const existing = await db.prepare('SELECT * FROM users WHERE email=?').get(email)
        if (path.endsWith('login')) {
          if (!existing?.password || !(await verify(password,existing.password,verifyLegacy))) fail(401,'Email or password is incorrect.')
          return await establish(res,existing)
        }
        if (existing) fail(409,'This email already has an account.')
        if (password.length < (secure?12:8)) fail(400,secure?'Use at least 12 characters for your password.':'Use at least eight characters for your password.')
        const role = ['admin','pandit'].includes(input.role) ? input.role : 'devotee'
        if (role !== 'devotee' && (!staffCode[role] || staffCode[role] !== field(input,'code',200))) fail(403,'Staff registration code is invalid or unavailable.')
        const account = {id:randomUUID(),name:field(input,'name',100,true),email,password:await hash(password,passwordRounds),role}
        const inserted=await db.prepare('INSERT INTO users VALUES (?,?,?,?,?) ON CONFLICT(email) DO NOTHING').run(account.id,account.name,email,account.password,role)
        if (!inserted.changes) fail(409,'This email already has an account.')
        return await establish(res,account)
      }
      if (path==='/api/events' && method==='GET') {
        const events=user?.role==='admin'?await db.prepare('SELECT * FROM ritual_events ORDER BY day LIMIT 200').all():
          await db.prepare('SELECT * FROM ritual_events WHERE active=1 AND day>=? ORDER BY day LIMIT 100').all(today())
        return send(res,{events})
      }
      if (path==='/api/events' && method==='POST') {
        if (user?.role!=='admin') fail(403,'Operations access is required.')
        const values=await read(req)
        const {kind,service,temple}=values
        const options=kind==='pooja'?catalog.rituals:kind==='chadhava'?topics.chadhava:[]
        if (!options.some(item=>item.id===service)||!topics.temples.some(item=>item.id===temple)) fail(400,'Choose a supported ritual and temple.')
        const id=randomUUID()
        await db.prepare('INSERT INTO ritual_events(id,kind,service,temple,day,title,description) VALUES (?,?,?,?,?,?,?)')
          .run(id,kind,service,temple,date(values,'day',true),field(values,'title',100,true),field(values,'description',900,true))
        return send(res,{id},201)
      }
      if (path.startsWith('/api/events/') && method==='PATCH') {
        if (user?.role!=='admin') fail(403,'Operations access is required.')
        const {active}=await read(req)
        if (typeof active!=='boolean') fail(400,'Choose whether the event is active.')
        const result=await db.prepare('UPDATE ritual_events SET active=? WHERE id=?').run(active?1:0,path.split('/').at(-1))
        if (!result.changes) fail(404,'Event not found.')
        return send(res,{active})
      }
      if (path==='/api/solar' && method==='GET') {
        const city=url.searchParams.get('city')||'Ujjain'
        const day=date({day:url.searchParams.get('date')||today()},'day')
        if (!Object.hasOwn(solarCities,city)||day<'1900-01-01'||day>'2100-12-31') fail(400,'Choose a supported city and a date from 1900 through 2100.')
        return send(res,{...solarTimes(city,day),cities:Object.keys(solarCities)})
      }
      if (await retail(req,res,path,user)) return
      if (await devotional(req,res,path,user)) return
      if (!user) fail(401,'Sign in to continue.')
      if (path === '/api/requests' && method === 'GET') {
        const query = 'SELECT * FROM requests '
        const sort = ' ORDER BY created DESC'
        const rows = user.role === 'admin' ? await db.prepare(query+sort).all() : user.role === 'pandit'
          ? await db.prepare(query+"WHERE assigned=? OR (assigned IS NULL AND status='Requested' AND kind!='support')"+sort).all(user.id)
          : await db.prepare(query+'WHERE owner=?'+sort).all(user.id)
        const staff = user.role === 'admin' ? await db.prepare("SELECT id,name FROM users WHERE role='pandit' ORDER BY name").all() : []
        return send(res,{requests:rows.map(row => {
          const value = requestView(row)
          if (user.role === 'pandit' && !row.assigned) value.details = {date:value.details.date}
          return value
        }),staff})
      }
      if (path === '/api/requests' && method === 'POST') {
        if (user.role !== 'devotee') fail(403,'Use a devotee account to submit a request.')
        const input = await read(req)
        const kind = field(input,'kind',20,true)
        const id = field(input,'id',36,true)
        if (!/^[0-9a-f-]{36}$/.test(id)) fail(400,'Invalid request ID.')
        const existing = await db.prepare('SELECT * FROM requests WHERE id=?').get(id)
        if (existing?.owner === user.id) return send(res,requestView(existing))
        if (existing) fail(409,'Request ID is already in use.')
        const campaign=field(input,'campaign',36)
        let event
        if (campaign) {
          event=await db.prepare('SELECT * FROM ritual_events WHERE id=? AND active=1 AND day>=?').get(campaign,today())
          if (!event||event.kind!==kind||event.service!==input.service) fail(409,'This event is unavailable.')
          input.date=event.day
          input.temple=event.temple
        }
        const [title,details] = booking(catalog,kind,input)
        if (event) {
          details.event=event.title
          details.date=event.day
          details.temple=topics.temples.find(item=>item.id===event.temple).name
        }
        const created = new Date().toISOString()
        const history = [{status:'Requested',date:created}]
        const inserted=await db.prepare('INSERT INTO requests VALUES (?,?,NULL,?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING').run(id,user.id,kind,title,'Requested',JSON.stringify(details),JSON.stringify(history),created)
        if (!inserted.changes) {
          const concurrent=await db.prepare('SELECT * FROM requests WHERE id=?').get(id)
          if (concurrent?.owner===user.id) return send(res,requestView(concurrent))
          fail(409,'Request ID is already in use.')
        }
        return send(res,{id,status:'Requested'},201)
      }
      const match = path.match(/^\/api\/requests\/([a-f0-9-]+)$/)
      if (match && method === 'PATCH') {
        const input = await read(req)
        const saved = await db.prepare('SELECT * FROM requests WHERE id=?').get(match[1])
        if (!saved || (user.role === 'devotee' && saved.owner !== user.id) ||
          (user.role === 'pandit' && (saved.kind === 'support' || (saved.assigned && saved.assigned !== user.id)))) fail(404,'Request not found.')
        if (input.expected !== saved.status) fail(409,'This request changed. Refresh and try again.')
        const row = requestView(saved)
        const next = await transition(db,row,input,user)
        row.history.push({status:next,date:new Date().toISOString()})
        const update = await db.prepare('UPDATE requests SET assigned=?,status=?,details=?,history=? WHERE id=? AND status=?').run(row.assigned,next,JSON.stringify(row.details),JSON.stringify(row.history),row.id,saved.status)
        if (!update.changes) fail(409,'This request changed. Refresh and try again.')
        return send(res,{...row,status:next})
      }
      fail(404,'Page not found.')
    } catch (error) {
      if (!error.status && error.code !== 'ENOENT') console.error(error)
      send(res,{error:error.status ? error.message : error.code === 'ENOENT' ? 'File not found.' : 'Something went wrong.'},error.status || (error.code === 'ENOENT' ? 404 : 500))
    }
  }
}

